import os
import re

from importlib.util import spec_from_file_location, module_from_spec


UTE_USER = '/home/ute/'
GERRIT_PATH = os.path.join(UTE_USER, 'testline_configuration')
ROBOTLTE_PATH = os.path.join(UTE_USER, 'robotlte', 'custom-config')


def is_iphy(logger):
    try:
        config, _ = get_ute_tl_config()
        return hasattr(config, 'iphy') and bool(config.iphy)
    except Exception as err:
        logger.debug(f'ute_config_loader.unexpected {err}, {type(err)}')
        return False


def get_ute_tl_config():
    """
    Fetch testline configuration base on testline location and name.

    :raise ValueError
    :return: UTE testline configuration as 'kind of' dict
    :rtype: ute_testline_configuration.ute_config.UTE_CONFIG
    """
    tl_name = get_tl_name()
    module_path = get_config_module_path(tl_name)
    config = load_tl_config(module_path, tl_name)
    return config.tl, config.tl_config if hasattr(config, 'tl_config') else None


def load_tl_config(module_path, tl_name):
    spec = spec_from_file_location(tl_name, module_path)
    config = module_from_spec(spec)
    spec.loader.exec_module(config)
    return config


def get_config_module_path(tl_name):
    if _is_gerrit_path(tl_name):
        module_path = os.path.join(GERRIT_PATH, tl_name, '__init__.py')
    else:
        module_path = os.path.join(ROBOTLTE_PATH, tl_name, '__init__.py')
    return module_path


def _is_gerrit_path(tl_name):
    return os.path.exists(os.path.join(GERRIT_PATH, tl_name))


def get_tl_name():
    # type: () -> str
    """
    Return testline name.

    :raise: AttributeError
    :return: testline name
    :rtype: str
    """
    vars_to_look_for_tl_name = {
        _get_env_variable('SESSION_MANAGER'): re.compile('local/(.*?):'),
        os.uname()[1]: re.compile('(.*)')}
    for var_value, var_re in list(vars_to_look_for_tl_name.items()):
        if var_value:
            tl_name = var_re.search(var_value).group(1)
            tl_name = _parse_tl_name(tl_name)
            return tl_name
    else:
        raise AttributeError('Could not get testline name')


def _get_env_variable(env_name):
    # type: (str) -> str
    """
    Return value od env. variable as string.

    :param env_name:
    :type env_name:
    :return: value of env. variable or empty string
    :rtype: str
    """
    try:
        return os.environ[env_name]
    except KeyError:
        return ''


def _parse_tl_name(tl_name):
    # type: (str) -> str
    """
    Parese testline name to fulfill naminig conventions.

    :param tl_name: testline name
    :type tl_name: str
    :return: parsed testlien name
    :rtype: str
    """
    not_single_testline = re.search(r'-\d+$', tl_name)  # name end with number
    if not_single_testline:
        tl_name = tl_name[:not_single_testline.start()]
    tl_name = tl_name.replace('-', '_')
    return tl_name
